import{_ as e,o as r,c as d,ag as o}from"./chunks/framework.DNmTgtHf.js";const m=JSON.parse('{"title":"Practice Problems & Interview Questions","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/reference/PracticeProblems.md","filePath":"todo/study_plan/reference/PracticeProblems.md"}'),i={name:"todo/study_plan/reference/PracticeProblems.md"};function n(a,t,s,l,c,h){return r(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="practice-problems-interview-questions" tabindex="-1">Practice Problems &amp; Interview Questions <a class="header-anchor" href="#practice-problems-interview-questions" aria-label="Permalink to &quot;Practice Problems &amp; Interview Questions&quot;">​</a></h1><p>Curated practice bank for the 12-week Sprint and standing rehearsal throughout. Problems are <em>intentionally not answered here</em> — that&#39;s your practice work. Pick a problem, set a timer, build/explain solo, then verify against the listed patterns/concepts.</p><h2 id="how-to-use-this-bank" tabindex="-1">How to use this bank <a class="header-anchor" href="#how-to-use-this-bank" aria-label="Permalink to &quot;How to use this bank&quot;">​</a></h2><ul><li><strong>Pick problems matching your current weak Part.</strong> If Concurrency is weak, do LRU/LFU + BookMyShow.</li><li><strong>Time-box ruthlessly.</strong> Machine-coding rounds in real interviews are 45–90 min. Use the listed time.</li><li><strong>Verbalize, don&#39;t read.</strong> Explain the design out loud while building it. That&#39;s the interview signal.</li><li><strong>Repeat the hard ones.</strong> Hard problems should be done 2–3 times until fluent.</li></ul><hr><h2 id="section-1-machine-coding-lld-problems-25" tabindex="-1">Section 1: Machine Coding / LLD problems (25) <a class="header-anchor" href="#section-1-machine-coding-lld-problems-25" aria-label="Permalink to &quot;Section 1: Machine Coding / LLD problems (25)&quot;">​</a></h2><p>Bread and butter for SDE2 → senior interviews. Most companies do one in the loop. Each row gives the problem, difficulty, the GoF + supporting patterns it teaches, and a realistic time-box.</p><table tabindex="0"><thead><tr><th>#</th><th>Problem</th><th>Difficulty</th><th>Patterns it teaches</th><th>Time-box</th></tr></thead><tbody><tr><td>1</td><td><strong>Parking Lot</strong></td><td>Med</td><td>Strategy (pricing), Factory (vehicle), Singleton (registry)</td><td>60–90 min</td></tr><tr><td>2</td><td><strong>Splitwise</strong></td><td>Med</td><td>Strategy (split algos), Observer (notify), Graph (settlement)</td><td>60–90 min</td></tr><tr><td>3</td><td><strong>Snake &amp; Ladder</strong></td><td>Easy</td><td>State, Factory, Random/Strategy for dice</td><td>45–60 min</td></tr><tr><td>4</td><td><strong>Chess</strong></td><td>Hard</td><td>State, Strategy (piece moves), Command (undo), Memento</td><td>90–120 min</td></tr><tr><td>5</td><td><strong>Tic-Tac-Toe</strong></td><td>Easy</td><td>State, Strategy (win-check)</td><td>30–45 min</td></tr><tr><td>6</td><td><strong>Elevator System</strong></td><td>Med</td><td>State, Strategy (scheduling), Observer (button presses), Singleton</td><td>60–90 min</td></tr><tr><td>7</td><td><strong>LRU Cache</strong></td><td>Med</td><td>Data structure: HashMap + Doubly Linked List</td><td>45–60 min</td></tr><tr><td>8</td><td><strong>LFU Cache</strong></td><td>Hard</td><td>HashMap-of-HashMaps + DLL per frequency</td><td>60–90 min</td></tr><tr><td>9</td><td><strong>Rate Limiter (Token Bucket / Sliding Window)</strong></td><td>Med</td><td>Strategy (algo choice), Singleton</td><td>45–60 min</td></tr><tr><td>10</td><td><strong>Logger with log levels</strong></td><td>Easy</td><td>Chain of Responsibility, Singleton</td><td>45 min</td></tr><tr><td>11</td><td><strong>In-memory KV store with TTL</strong></td><td>Med</td><td>Background eviction, expiration heap</td><td>60–90 min</td></tr><tr><td>12</td><td><strong>ATM</strong></td><td>Med</td><td>State, Strategy (withdrawal algo), Chain of Responsibility</td><td>60–90 min</td></tr><tr><td>13</td><td><strong>Vending Machine</strong></td><td>Easy</td><td>State, Strategy</td><td>45–60 min</td></tr><tr><td>14</td><td><strong>Library Management</strong></td><td>Med</td><td>Entity modeling, search, member ops</td><td>60–90 min</td></tr><tr><td>15</td><td><strong>BookMyShow / Movie Ticket Booking</strong></td><td>Hard</td><td>Singleton, concurrency (seat lock), optimistic locking, State</td><td>90–120 min</td></tr><tr><td>16</td><td><strong>Notification Dispatch (multi-channel)</strong></td><td>Med</td><td>Strategy (per channel), Observer, Chain of Responsibility</td><td>60–90 min</td></tr><tr><td>17</td><td><strong>Job Scheduler / Cron</strong></td><td>Med</td><td>Strategy (schedule type), Priority Queue, Observer</td><td>60–90 min</td></tr><tr><td>18</td><td><strong>Food Ordering (Swiggy/Zomato core)</strong></td><td>Hard</td><td>State, Strategy, Observer, Factory</td><td>90–120 min</td></tr><tr><td>19</td><td><strong>Ride-sharing core (Uber/Ola)</strong></td><td>Hard</td><td>State, Strategy (matching), Observer, geo-hashing</td><td>90–120 min</td></tr><tr><td>20</td><td><strong>URL Shortener (LLD scope)</strong></td><td>Easy</td><td>Encoding strategy, in-memory map</td><td>45–60 min</td></tr><tr><td>21</td><td><strong>Bowling Game scorer</strong></td><td>Easy</td><td>State, rules engine</td><td>45 min</td></tr><tr><td>22</td><td><strong>Connection pool implementation</strong></td><td>Med</td><td>Object Pool, Singleton</td><td>45–60 min</td></tr><tr><td>23</td><td><strong>In-memory Pub-Sub system</strong></td><td>Med</td><td>Observer, Strategy (delivery semantics)</td><td>60–90 min</td></tr><tr><td>24</td><td><strong>KYC verification state machine</strong> 🔐</td><td>Med</td><td>State, Strategy, Chain of Responsibility — <em>directly your domain</em></td><td>60–90 min</td></tr><tr><td>25</td><td><strong>Document upload pipeline with retry + idempotency</strong> 🔐</td><td>Med</td><td>Idempotency Key, Retry pattern, Strategy</td><td>60 min</td></tr></tbody></table><p>🔐 = directly relevant to your KYC platform — high leverage for promotion narratives.</p><p><strong>Recommended Sprint plan for LLD practice:</strong></p><ul><li><strong>Saturday Week 4 onwards:</strong> 1 LLD problem per Saturday (Easy → Medium ramp).</li><li><strong>From Saturday Week 6:</strong> alternate weekends with HLD (LLD one Saturday, HLD the next).</li><li><strong>Week 12 (mock-loop week):</strong> 1 LLD problem back-to-back with 1 HLD + 1 behavioral, simulating an interview loop.</li></ul><p><strong>Coverage goal:</strong> ≥4 LLD problems walked end-to-end by Week 12. Don&#39;t try to do all 25 — diminishing returns after the first handful once you&#39;ve internalized the patterns.</p><hr><h2 id="section-2-hld-system-design-problems-20" tabindex="-1">Section 2: HLD / System Design problems (20) <a class="header-anchor" href="#section-2-hld-system-design-problems-20" aria-label="Permalink to &quot;Section 2: HLD / System Design problems (20)&quot;">​</a></h2><p>Heaviest interview block at senior+. Each row gives the problem, difficulty, and the key concepts you must surface in the design discussion.</p><table tabindex="0"><thead><tr><th>#</th><th>Problem</th><th>Difficulty</th><th>Key concepts to surface</th><th>Time-box</th></tr></thead><tbody><tr><td>1</td><td><strong>URL shortener (full scale)</strong></td><td>Easy</td><td>Hashing, DB sharding, caching, read-heavy ratio</td><td>30–45 min</td></tr><tr><td>2</td><td><strong>Pastebin</strong></td><td>Easy</td><td>Object storage, expiration, access control</td><td>30–45 min</td></tr><tr><td>3</td><td><strong>Twitter / News feed</strong></td><td>Hard</td><td>Fan-out-on-write vs read, timeline generation, ranking, celebrity problem</td><td>60 min</td></tr><tr><td>4</td><td><strong>Instagram (image-heavy feed)</strong></td><td>Hard</td><td>CDN, object storage, image variants, feed generation</td><td>60 min</td></tr><tr><td>5</td><td><strong>WhatsApp / Chat</strong></td><td>Hard</td><td>Long-poll/WebSockets, message queue, presence, e2e crypto basics</td><td>60 min</td></tr><tr><td>6</td><td><strong>YouTube / Video streaming</strong></td><td>Hard</td><td>CDN, transcoding pipeline, adaptive bitrate, recommendations</td><td>60 min</td></tr><tr><td>7</td><td><strong>Uber / Ride-sharing</strong></td><td>Hard</td><td>Geo (H3/S2), matching, dispatch, surge pricing</td><td>60–90 min</td></tr><tr><td>8</td><td><strong>Dropbox / File sync</strong></td><td>Hard</td><td>Chunking, dedup, sync protocol, conflict resolution</td><td>60 min</td></tr><tr><td>9</td><td><strong>Google Drive / Collaborative editing</strong></td><td>Hard</td><td>OT / CRDT, real-time sync, presence</td><td>60 min</td></tr><tr><td>10</td><td><strong>Notification service</strong></td><td>Med</td><td>Fan-out, retries, channels, idempotency, ordering</td><td>45–60 min</td></tr><tr><td>11</td><td><strong>Distributed cache (Redis-like)</strong></td><td>Hard</td><td>Consistent hashing, replication, eviction, persistence</td><td>60 min</td></tr><tr><td>12</td><td><strong>Distributed message queue (Kafka-like)</strong></td><td>Hard</td><td>Partitioning, replication, offsets, exactly-once semantics</td><td>60–90 min</td></tr><tr><td>13</td><td><strong>Rate limiter (distributed)</strong></td><td>Med</td><td>Algorithms, Redis-backed counters, sliding windows</td><td>45–60 min</td></tr><tr><td>14</td><td><strong>Web crawler</strong></td><td>Med</td><td>URL frontier, dedup, politeness, distributed coordination</td><td>45–60 min</td></tr><tr><td>15</td><td><strong>Search autocomplete / Typeahead</strong></td><td>Med</td><td>Trie, ranking, latency targets, hot-prefix caching</td><td>45–60 min</td></tr><tr><td>16</td><td><strong>KYC / identity verification platform</strong> 🔐</td><td>Hard</td><td>Vendor orchestration, state machine, multi-tenant, region pinning, webhooks — <em>directly your domain</em></td><td>60–90 min</td></tr><tr><td>17</td><td><strong>Payment system</strong></td><td>Hard</td><td>Idempotency, ledger (double-entry), saga, reconciliation</td><td>60–90 min</td></tr><tr><td>18</td><td><strong>Ad-click counter at scale</strong></td><td>Med</td><td>Counters, Lambda arch (or pure stream), dedup, fraud signals</td><td>45–60 min</td></tr><tr><td>19</td><td><strong>Distributed locks</strong></td><td>Med</td><td>Redis Redlock, ZooKeeper, fencing tokens, failure modes</td><td>45 min</td></tr><tr><td>20</td><td><strong>Logging / Analytics system (ELK-style)</strong></td><td>Med</td><td>Ingest pipeline, indexing, querying, retention tiers</td><td>45–60 min</td></tr></tbody></table><p>🔐 = directly your domain — practice this one <em>especially well</em>. It&#39;s your portfolio piece.</p><p><strong>Recommended Sprint plan for HLD practice:</strong></p><ul><li><strong>Saturday Week 6 onwards:</strong> 1 HLD problem per Saturday, alternating with LLD weekends. Rotate focus (1 storage-heavy, 1 compute-heavy, 1 KYC-domain, repeat).</li><li><strong>Week 12 (mock-loop week):</strong> 1 HLD problem back-to-back with 1 LLD + 1 behavioral.</li><li><strong>Always finish #16 (KYC platform)</strong> before any interview where senior is on the line — do it <strong>twice</strong> during the Sprint.</li></ul><p><strong>Coverage goal:</strong> ≥4 HLD problems walked end-to-end by Week 12 + your KYC platform polished (done twice).</p><hr><h2 id="section-3-design-pattern-interview-questions-20" tabindex="-1">Section 3: Design pattern interview questions (20) <a class="header-anchor" href="#section-3-design-pattern-interview-questions-20" aria-label="Permalink to &quot;Section 3: Design pattern interview questions (20)&quot;">​</a></h2><p>Asked in both coding rounds and design discussions. Each question lists what the interviewer is actually testing — answer the <em>underlying concept</em>, not the surface question.</p><table tabindex="0"><thead><tr><th>#</th><th>Question</th><th>What&#39;s actually being tested</th></tr></thead><tbody><tr><td>1</td><td>Walk through the 5 ways to implement Singleton in Java, and why Bill Pugh is preferred.</td><td>Class loading, JMM (happens-before), DCL pitfalls, thread safety</td></tr><tr><td>2</td><td>When would you use a Builder over a constructor with many optional params?</td><td>Immutability, readability, validation, telescoping-constructor anti-pattern</td></tr><tr><td>3</td><td>Hand-written Builder vs Lombok <code>@Builder</code> — what&#39;s lost with the annotation?</td><td>Required-field enforcement, validation in <code>build()</code>, custom logic</td></tr><tr><td>4</td><td>Factory Method vs Abstract Factory — concrete difference?</td><td>Product hierarchy depth, when one factory becomes many</td></tr><tr><td>5</td><td>Strategy vs State pattern — sounds similar; how do you tell them apart?</td><td>Behavior swap externally vs internal state transitions; who decides the change</td></tr><tr><td>6</td><td>Strategy vs Template Method — when each?</td><td>Composition (Strategy) vs inheritance (Template); extension points</td></tr><tr><td>7</td><td>Observer push vs pull — tradeoffs?</td><td>Decoupling vs efficiency; what subscriber needs to know</td></tr><tr><td>8</td><td>Decorator vs Subclassing — when prefer each?</td><td>Open/Closed principle, runtime composition vs compile-time hierarchy</td></tr><tr><td>9</td><td>Adapter vs Facade — both wrap something; what&#39;s the actual difference?</td><td>Interface incompatibility (Adapter) vs interface complexity simplification (Facade)</td></tr><tr><td>10</td><td>Why is Singleton sometimes called an anti-pattern?</td><td>Testability, hidden coupling, global state, parallel test runs</td></tr><tr><td>11</td><td>Chain of Responsibility — design choices (default handler? short-circuit? logging at each step?).</td><td>Order sensitivity, fall-through semantics, side effects</td></tr><tr><td>12</td><td>Proxy types — virtual, remote, protection — give one real example each.</td><td>Lazy init (virtual), network/RPC (remote), ACL/auth (protection)</td></tr><tr><td>13</td><td>Visitor pattern — why is it controversial? When does it actually fit?</td><td>Stable class hierarchy + growing operations, double dispatch, OO-vs-procedural</td></tr><tr><td>14</td><td>Composite vs Decorator — both recursive; what&#39;s the actual difference?</td><td>Tree structure (Composite) vs behavior wrapping (Decorator)</td></tr><tr><td>15</td><td>Identify the design pattern from this snippet: <code>Spring&#39;s JdbcTemplate.execute(...)</code>.</td><td>Template Method recognition</td></tr><tr><td>16</td><td>Saga: orchestration vs choreography — which when?</td><td>Central control vs event-driven; complexity vs coupling</td></tr><tr><td>17</td><td>Why Repository pattern? What does it abstract away?</td><td>DDD, persistence ignorance, testability via in-memory impl</td></tr><tr><td>18</td><td>DI vs DIP — clarify the distinction.</td><td>Principle (DIP — depend on abstractions) vs implementation technique (DI — inject the abstraction)</td></tr><tr><td>19</td><td>When does the Outbox pattern earn its complexity?</td><td>Reliable event publishing without 2PC, transactional consistency between DB write + message emit</td></tr><tr><td>20</td><td>Name 5 design patterns Spring uses internally, with concrete examples.</td><td>Factory (BeanFactory), Proxy (AOP), Template Method (JdbcTemplate), Strategy (TaskScheduler implementations), Observer (ApplicationEventPublisher)</td></tr></tbody></table><p><strong>Recommended Sprint plan for Design Pattern Qs:</strong></p><ul><li><strong>Early Sprint (Weeks 1–6):</strong> Read each question and self-rate. ✅/🟡/🔴 confidence per question.</li><li><strong>Mid-to-late Sprint (Weeks 7–12):</strong> Rehearse 🔴 / weak-🟡 questions out loud against a timer (2-min answers).</li><li><strong>The week before any interview:</strong> Run through all 20 in one session as a vocabulary refresh.</li></ul><hr><h2 id="section-4-other-practice" tabindex="-1">Section 4: Other practice <a class="header-anchor" href="#section-4-other-practice" aria-label="Permalink to &quot;Section 4: Other practice&quot;">​</a></h2><p>Cross-cutting prep that doesn&#39;t fit the above buckets.</p><h3 id="_4-1-behavioral-star-stories" tabindex="-1">4.1 Behavioral / STAR stories <a class="header-anchor" href="#_4-1-behavioral-star-stories" aria-label="Permalink to &quot;4.1 Behavioral / STAR stories&quot;">​</a></h3><p>Prepare <strong>5–8 stories</strong> covering the following themes. Each story = ~2-minute STAR narrative (Situation, Task, Action, Result). Same story can serve multiple themes.</p><table tabindex="0"><thead><tr><th>#</th><th>Theme</th><th>Why interviewers ask</th></tr></thead><tbody><tr><td>1</td><td>A technically ambitious project you owned</td><td>Tests scope, design judgment, ownership</td></tr><tr><td>2</td><td>A production incident you handled</td><td>Tests calm under pressure, debugging, communication</td></tr><tr><td>3</td><td>A disagreement with a peer / manager you resolved</td><td>Tests collaboration, influence without authority</td></tr><tr><td>4</td><td>A time you mentored a junior engineer</td><td>Tests senior signal (you grow others, not just yourself)</td></tr><tr><td>5</td><td>A failure / mistake and what you learned</td><td>Tests growth mindset, accountability</td></tr><tr><td>6</td><td>A cross-team / cross-functional project</td><td>Tests influence and stakeholder management</td></tr><tr><td>7</td><td>A time you pushed back on requirements</td><td>Tests engineering judgment, principled disagreement</td></tr><tr><td>8</td><td>A time you simplified something over-engineered</td><td>Tests YAGNI, taste, restraint</td></tr></tbody></table><p><strong>Where to draft:</strong> maintain a <code>study_plan/STARStories.md</code> (create when Sprint Week 8 starts, not earlier — drafts will be stale by then).</p><h3 id="_4-2-domain-cross-questions-already-in-per-part-docs" tabindex="-1">4.2 Domain cross-questions (already in per-Part docs) <a class="header-anchor" href="#_4-2-domain-cross-questions-already-in-per-part-docs" aria-label="Permalink to &quot;4.2 Domain cross-questions (already in per-Part docs)&quot;">​</a></h3><p>These are interview rehearsal material, not new content:</p><table tabindex="0"><thead><tr><th>Source</th><th>Count</th><th>Use</th></tr></thead><tbody><tr><td><code>parts/Part_29_Domain_Patterns_KYC.md</code> § Cross-questions</td><td>55</td><td>KYC orchestration, scaling, reliability, compliance, security, domain depth, system-design — practice walking through each out loud, 2 min max</td></tr><tr><td><code>parts/Part_31_Platform_Deep_Cuts.md</code> § Cross-questions</td><td>26</td><td>Architecture &amp; flow, data &amp; state, scale &amp; performance, security &amp; SDK, compliance &amp; ops, vendor — your platform-specific war-story material</td></tr><tr><td><code>parts/Part_07_HLD_Distributed.md</code> § Trick questions</td><td>~5</td><td>Distributed systems gotchas</td></tr><tr><td><code>parts/Part_06_Databases.md</code> § Trick questions</td><td>~5</td><td>Isolation level / MVCC traps</td></tr><tr><td><code>parts/Part_01_Java_JVM.md</code> § Trick questions</td><td>~5</td><td>HashMap / String / Collections traps</td></tr><tr><td><code>parts/Part_02_Concurrency.md</code> § Trick questions</td><td>~5</td><td>JMM, volatile, deadlock gotchas</td></tr></tbody></table><blockquote><p><strong>Note:</strong> Part 29 § Cross-questions section 6 (&quot;System design cross-questions in your domain&quot;) covers 7 HLD problems that overlap with Section 2 of this doc (notably #16 KYC platform, #10 Notification service, #13 Distributed rate limiter). Don&#39;t double-rehearse — pick whichever framing helps that day.</p></blockquote><h3 id="_4-3-compensation-promotion-prep" tabindex="-1">4.3 Compensation &amp; promotion prep <a class="header-anchor" href="#_4-3-compensation-promotion-prep" aria-label="Permalink to &quot;4.3 Compensation &amp; promotion prep&quot;">​</a></h3><ul><li>Read <code>levels.fyi</code> for your level + region 2 weeks before any interview.</li><li>Skim <em>The Pragmatic Engineer</em> compensation reviews quarterly.</li><li>Maintain a brag doc (weekly notes) — your promotion currency. See <code>parts/Part_30_Interview_Career_Prep.md</code> § Quick recall.</li></ul><hr><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. How many LLD problems should I aim to solve in the Sprint?</strong> A. 8–10 with quality &gt; 25 with rush. Pick across difficulties: 3 Easy (warm-up), 4 Medium (core), 2-3 Hard (stretch).</p><p><strong>Q. Which HLD problem is non-negotiable for me?</strong> A. #16 (KYC / identity verification platform). It&#39;s your domain — interviewers will <em>expect</em> a polished walk-through. Practice it every other week.</p><p><strong>Q. How to use Section 3 (design pattern Qs)?</strong> A. Survey first (✅/🟡/🔴), then rehearse only the 🔴 + weak-🟡. Don&#39;t waste rehearsal time on ones already cold.</p><p><strong>Q. When do I draft STAR stories?</strong> A. Mid-Sprint onwards (around Week 7–8). Earlier drafts get stale and you&#39;ll rewrite them anyway. Run them live in the Week 12 mock-loop.</p><p><strong>Q. Where do the existing cross-questions live?</strong> A. <code>parts/Part_29_Domain_Patterns_KYC.md</code> § Cross-questions (55 items) + <code>parts/Part_31_Platform_Deep_Cuts.md</code> § Cross-questions (26 items). Don&#39;t duplicate them here — practice from those docs directly.</p>',46)])])}const g=e(i,[["render",n]]);export{m as __pageData,g as default};
